    if (seg.length >= 3 && !IG_GENERIC_JA.test(seg)) { var k = normText(seg); if (/[\u3040-\u30ff\u4e00-\u9fff]/.test(k) && k.length >= 3) keys.push({ k: k, n: 2, ja: true }); }
